      "locale": "en-US",
      "ref.share": "Share my invite",
      "ref.copyPi": "Copy Pi Browser link",
      "ref.hintBrowser": "Friends must open the link in Pi Browser. If it opens in another browser, they should copy it and paste it into Pi Browser's address bar.",
      "share.text": "Join me in Pi Oasis 🌴 Farm, build a city and win weekly Pi prizes! Open this link in Pi Browser: {link} (or type {host} in Pi Browser) — my invite code: {code}",
