      "help.derby.d": "في تبويب المزرعة، افتح «سباق الجمال». درّب سرعة جملك وتحمّله وانطلاقته بالتمر (أو بالعلف الذهبي)، واختر خطة، وسابق 5 جمال أخرى: جمال لاعبين لديهم كؤوس قريبة من كؤوسك، أو جمال الحاسوب. 8 سباقات مجانية كل يوم، و4 إضافية بعد مشاهدة إعلان Pi. كل مركز يربح كؤوسًا وتمرًا، والكؤوس ترفعك إلى بطولات أعلى تدفع أكثر. وكل أسبوع يحصل أفضل 100 حسب الكؤوس على التمر. عملة Pi تشتري العلف الذهبي وسلالات أفضل (السريع، الملكي، الأسطورة)؛ ولا توجد رسوم دخول ولا رهان.",
