      "help.earn.d": "في تبويب المزرعة، افتح Jerry Media Earnings. شاهد إشهار Pi قصير وخذ التمر، بلا حد يومي: أول 10 إشهارات فالنهار كيعطيو أكثر وأكثر (من 50 حتى 200 تمرة)، ومن بعد كل إشهار زايد كيعطي 50 تمرة، مع 45 ثانية بين كل إشهار. الإشهار الخامس كيحافظ على السلسلة ديالك وكيزيد دورة مجانية فالعجلة، والعاشر كيزيد عملات كومبات وJRY. المستوى ديالك كيطلع مع كل إشهار وكيكبّر المكافآت. باش تحوّل النقاط لـ Pi، بيعها فسوق النقاط واسحب ابتداءً من 5 Pi.",
