      "help.pmarket.t": "سوق النقاط 🏪",
      "help.pmarket.d": "في تبويب المزرعة، افتح سوق النقاط. للبيع: اختر التمر أو عملات كومبات، ثم الكمية والسعر الإجمالي بـ Pi. تخرج النقاط من لعبتك وتنتظر في العرض، ويمكنك الإلغاء في أي وقت لتسترجعها. عندما يشتري لاعب، يدفع بـ Pi للتطبيق ويستلم النقاط، ويُضاف 75% من السعر إلى رصيد مبيعاتك (رسوم 25%، وجزء منها يذهب لجائزة الأسبوع). ابتداءً من 5 Pi اضغط «اسحب» فيُرسل الـ Pi إلى محفظتك. النقاط المشتراة هنا لا تُحتسب أبدًا في ترتيب الأسبوع.",
