      "help.derby.t": "Course de chameaux 🏁",
      "help.derby.d": "Dans l'onglet Ferme, ouvre la Course de chameaux. Entraîne la vitesse, l'endurance et le départ de ton chameau avec des dattes (ou du fourrage doré), choisis une tactique et affronte 5 autres chameaux : ceux de joueurs ayant à peu près tes trophées, ou des chameaux de l'ordinateur. 8 courses gratuites par jour, plus 4 après une pub Pi. Chaque place gagne des trophées et des dattes ; les trophées te font monter vers des coupes qui paient plus. Chaque semaine, le top 100 en trophées reçoit des dattes. Les Pi achètent du fourrage doré et de meilleures races (Rapide, Royal, Légende) ; pas de mise, pas de pari.",
