      "help.arcade.t": "Jerry Arcade 🕹️",
      "help.arcade.d": "Dans l'onglet Ferme, ouvre Jerry Arcade. Deux jeux d'adresse gratuits : Mémoire de l'oasis (trouve les 8 paires en un minimum de coups, jusqu'à 200 dattes) et Attrape-dattes (30 secondes, attrape dattes et pièces, évite les scorpions, jusqu'à 300 dattes). Chaque jeu donne des dattes 5 fois par jour ; ensuite tu peux continuer pour le plaisir. Les meilleurs scores du jour sont affichés.",
      "help.showcase.t": "Vitrine des entreprises 📣",
