      "help.pmarket.d": "Dans l'onglet Ferme, ouvre le Marché des points. Pour vendre : choisis dattes ou pièces Kombat, la quantité et ton prix total en Pi. Les points quittent ton jeu et attendent dans l'offre ; annule quand tu veux pour les récupérer. Quand un joueur achète, il paie en Pi à l'application et reçoit les points ; 75 % du prix s'ajoute à ton solde de ventes (25 % de frais, dont une partie alimente la cagnotte de la semaine). Dès 5 Pi, appuie sur Retirer et les Pi sont envoyés à ton portefeuille. Les points achetés ici ne comptent jamais au classement.",
