      "ref.hintBrowser": "Tes amis doivent ouvrir le lien dans Pi Browser. S'il s'ouvre dans un autre navigateur, ils doivent le copier et le coller dans la barre d'adresse de Pi Browser.",
      "share.text": "Rejoins-moi dans Pi Oasis 🌴 Cultive, construis une ville et gagne des prix Pi chaque semaine ! Ouvre ce lien dans Pi Browser : {link} (ou tape {host} dans Pi Browser) — mon code d'invitation : {code}",
